#include <string>
#include <iostream>

auto factorial(auto n) {
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

auto fib(auto n) {
    if (n <= 1) {
        return n;
    }
    auto a = 0;
    auto b = 1;
    auto i = 2;
    while (i <= n) {
        auto c = a + b;
        a = b;
        b = c;
        i = i + 1;
    }
    return b;
}

